indices=[('GRASP_END',baseidx),('TRANSPORT_START',int(np.argmin(abs(t-ph['TRANSPORT'])))),('ALIGN_START',int(np.argmin(abs(t-ph['ALIGN'])))),('INSERT_START',insertidx)]
