indices += [('MAX_TILT',int(np.argmax(tilt))),('t45',int(np.argmin(abs(t-45.)))),('FINAL',len(t)-1)]
snapshots=[]
for name,i in indices:
 snapshots.append(dict(label=name,time_s=float(t[i]),phase=rows[i]['phase'],tilt_deg=float(tilt[i]),cup_origin_xy_error_mm=(xy[i]*1000).tolist(),object_z_axis_world=axis[i].tolist(),cup_origin_world_m=position[i],actual_tcp_world_m=tcp[i],target_tcp_world_m=cmd[i],actual_bottom_gap_mm=float(gap[i]*1000),cup_hand_translation_change_mm=hand_delta[i]*1000,cup_tcp_world_offset_change_mm=world_delta[i]*1000,cup_hand_rotation_change_deg=float(relative_angle[i]),finger_normal_N=finger[i],finger_position_mm=finger_q[i]*1000,target_bottom_force_N=target_force[i],target_wall_normal_N=normal[i],target_wall_friction_N=friction[i],fingers_friction_sum_N=fing_fric[i],source_penetration_m=rows[i]['source_penetration_m']))
write_new(out/'selected_actual_states.json',dict(schema='labsim.V0_demo03.contact_diagnosis.states.v1',baseline='actual GRASP end at13.5s, same old-relative sample used by controller',states=snapshots))
v0=hand[baseidx]-[0,0,.1];rotation_component=hand_rot[insertidx].apply(v0)-hand_rot[baseidx].apply(v0);translation_component=hand_rot[insertidx].apply(hand[insertidx]-hand[baseidx]);decomposition=dict(cup_xy_error_mm=xy[insertidx]*1000,tcp_actual_minus_command_xy_mm=(tcp[insertidx,:2]-cmd[insertidx,:2])*1000,held_world_offset_change_xy_mm=world_delta[insertidx,:2]*1000,command_plus_old_offset_minus_target_xy_mm=(cmd[insertidx,:2]+relative_world[baseidx,:2]-floor_xy)*1000,held_offset_translation_component_world_mm=translation_component*1000,held_offset_hand_rotation_component_world_mm=rotation_component*1000,actual_hand_rotation_change_deg=float(np.degrees((hand_rot[insertidx]*hand_rot[baseidx].inv()).magnitude())),formula='actual cup XY error = actual TCP-command error + current held world offset-old offset + command+old offset-target; no source pose changes')
